import type { Interfaces } from '@oclif/core';
/** The shape this module reads off an oclif flag definition. */
export interface FlagShape {
    type?: string | undefined;
    char?: string | undefined;
    aliases?: readonly string[] | undefined;
    charAliases?: readonly string[] | undefined;
}
/**
 * A command's telemetry behaviour, read off the command class as
 * `static telemetry`. Mirrors the sanity CLI's own hook, so a flag is excluded
 * the same way on both CLIs.
 */
export interface CommandTelemetry {
    redacted: readonly string[];
}
